(function(){function setIntrinsicDimensions(img){let imageNaturalWidth=img.naturalWidth,imagenaturalHeight=img.naturalHeight;if(!imageNaturalWidth||!imagenaturalHeight)return;let imageRenderedWidth=img.offsetWidth;if(!imageRenderedWidth)return;let imageRenderedHeight=Math.round(imageRenderedWidth*imagenaturalHeight/imageNaturalWidth);img.setAttribute(`width`,imageRenderedWidth),img.setAttribute(`height`,imageRenderedHeight)}document.querySelectorAll(`.widget_dfm_linkable_image_widget`).forEach(function(img){img.complete&&img.naturalWidth?setIntrinsicDimensions(img):img.addEventListener(`load`,function(){setIntrinsicDimensions(img)})})})();